1	export type Cell = [number, number];
2	
3	const SURVIVING_NEIGHBOUR_COUNTS = [2, 3];
4	
5	function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
6	  return x === otherX && y === otherY;
7	}
8	
9	function isAdjacent([x, y]: Cell, [otherX, otherY]: Cell): boolean {
10	  return Math.abs(otherX - x) <= 1 && Math.abs(otherY - y) <= 1;
11	}
12	
13	function isNeighbourOf(cell: Cell, other: Cell): boolean {
14	  return isAdjacent(cell, other) && !isSameCell(cell, other);
15	}
16	
17	function countLivingNeighbours(cell: Cell, livingCells: Cell[]): number {
18	  return livingCells.filter((other) => isNeighbourOf(cell, other)).length;
19	}
20	
21	function survives(cell: Cell, livingCells: Cell[]): boolean {
22	  return SURVIVING_NEIGHBOUR_COUNTS.includes(
23	    countLivingNeighbours(cell, livingCells),
24	  );
25	}
26	
27	const BIRTH_NEIGHBOUR_COUNT = 3;
28	
29	function isAlive(cell: Cell, livingCells: Cell[]): boolean {
30	  return livingCells.some((living) => isSameCell(cell, living));
31	}
32	
33	function candidates(livingCells: Cell[]): Cell[] {
34	  const found: Cell[] = [];
35	  for (const [x, y] of livingCells) {
36	    for (let dx = -1; dx <= 1; dx++) {
37	      for (let dy = -1; dy <= 1; dy++) {
38	        const candidate: Cell = [x + dx, y + dy];
39	        if (!isAlive(candidate, found)) found.push(candidate);
40	      }
41	    }
42	  }
43	  return found;
44	}
45	
46	export function nextGeneration(livingCells: Cell[]): Cell[] {
47	  return candidates(livingCells).filter((cell) =>
48	    isAlive(cell, livingCells)
49	      ? survives(cell, livingCells)
50	      : countLivingNeighbours(cell, livingCells) === BIRTH_NEIGHBOUR_COUNT,
51	  );
52	}
